def bootstrap_mean_interval(scores, samples=2000, seed=7):
    import random
    if not scores:
        raise ValueError("scores_required")
    rng = random.Random(seed)
    means = []
    for _ in range(samples):
        draw = [rng.choice(scores) for _ in scores]
        means.append(sum(draw) / len(draw))
    means.sort()
    return {"low": means[int(samples * .025)], "mean": sum(scores) / len(scores),
            "high": means[int(samples * .975)]}

