def allocate_tiles(images, total_tokens, reserved_text, tokens_per_tile=256):
    capacity = max(0, total_tokens - reserved_text) // tokens_per_tile
    result = {image["id"]: 0 for image in images}
    for image in sorted(images, key=lambda x: x["priority"], reverse=True):
        wanted = max(image.get("min_tiles", 1), image.get("requested_tiles", 1))
        result[image["id"]] = min(wanted, capacity)
        capacity -= result[image["id"]]
    return result

